insert into public.park_info (id, data, version) values ('kiara-artha', '{"name":"Kiara Artha Park","city":"Bandung","address":"Jl. Banten, Kebonwaru, Kec. Batununggal, Kota Bandung, Jawa Barat","center":[-6.9164043,107.642318],"zoom":18,"bounds":[[-6.9185,107.6392],[-6.9135,107.645]],"opening_hours":{"open":"07:00","close":"21:00"},"ticket":"Rp10.000 per orang (detikJabar, 2024) — cek kembali di loket","phone":"0822-1583-8889","instagram":"@kiaraarthapark","inaugurated":"2019-08-17","area_ha":13,"lake":{"center":[-6.9160874,107.6422657],"radius_m":30},"ring":[[-6.916259,107.643262],[-6.916159,107.643272],[-6.916058,107.643274],[-6.915957,107.643269],[-6.915858,107.643256],[-6.915761,107.643236],[-6.915667,107.643208],[-6.915576,107.643173],[-6.915489,107.64313],[-6.915407,107.643082],[-6.91533,107.643027],[-6.91526,107.642966],[-6.915196,107.642899],[-6.915139,107.642828],[-6.915089,107.642753],[-6.915047,107.642673],[-6.915014,107.642591],[-6.914988,107.642506],[-6.914972,107.642419],[-6.914964,107.642331],[-6.914965,107.642242],[-6.914974,107.642154],[-6.914993,107.642066],[-6.915019,107.64198],[-6.915055,107.641896],[-6.915098,107.641814],[-6.915149,107.641736],[-6.915208,107.641662],[-6.915273,107.641593],[-6.915345,107.641528],[-6.915423,107.641469],[-6.915506,107.641417],[-6.915593,107.64137],[-6.915685,107.64133],[-6.91578,107.641298],[-6.915878,107.641272],[-6.915977,107.641254],[-6.916077,107.641244],[-6.916178,107.641242],[-6.916279,107.641247],[-6.916378,107.64126],[-6.916475,107.64128],[-6.916569,107.641308],[-6.91666,107.641343],[-6.916747,107.641386],[-6.916829,107.641434],[-6.916906,107.641489],[-6.916976,107.64155],[-6.91704,107.641617],[-6.917097,107.641688],[-6.917147,107.641763],[-6.917189,107.641843],[-6.917222,107.641925],[-6.917248,107.64201],[-6.917264,107.642097],[-6.917272,107.642185],[-6.917271,107.642274],[-6.917262,107.642362],[-6.917243,107.64245],[-6.917217,107.642536],[-6.917181,107.64262],[-6.917138,107.642702],[-6.917087,107.64278],[-6.917028,107.642854],[-6.916963,107.642923],[-6.916891,107.642988],[-6.916813,107.643047],[-6.91673,107.643099],[-6.916643,107.643146],[-6.916551,107.643186],[-6.916456,107.643218],[-6.916358,107.643244],[-6.916259,107.643262]],"sources":[{"label":"Google Maps — Kiara Artha Park & tempat di sekitarnya","url":"https://maps.google.com/?q=-6.9164043,107.642318","accessed":"2026-11-16"},{"label":"detikJabar — Kiara Artha Park, Spot Rekreasi di Tengah Kota Bandung","url":"https://www.detik.com/jabar/wisata/d-7229191/kiara-artha-park-spot-rekreasi-di-tengah-kota-bandung"},{"label":"Orami — Kiara Artha Park (30 Sep 2024)","url":"https://www.orami.co.id/magazine/kiara-artha-park"},{"label":"Republika — Ayo Intip Keseruan di Kiara Artha Park (24 Agu 2019)","url":"https://news.republika.co.id/berita/pwoiiv0/ayo-intip-keseruan-di-kiara-artha-park-bandung"},{"label":"Pemkot Bandung — Bike on The Street Everybody Happy (BOSEH)","url":"https://www.bandung.go.id/sub-etalase/27/sepeda"}]}'::jsonb, '2026-11-24')
insert into public.poi (id, name, short_name, category_id, zone, location, radius_m, description, trigger_response, qr_code, data_source, is_published, summary, narration, activities, tips, best_times, keywords, art, status_note, source_place, sort_order) values ('P01', 'Pintu Utama Kiara Artha Park', 'Pintu Utama', 'akses', 'Gerbang barat, sisi Jl. Banten', extensions.st_setsrid(extensions.st_makepoint(107.6407033, -6.9161917), 4326)::extensions.geography, 25, 'Pintu masuk utama Kiara Artha Park berada di sisi barat, menghadap Jl. Banten. Dari sini jalur pejalan kaki mengarah ke lingkar Jl. Kiara Artha yang mengelilingi danau dan air mancur menari di tengah taman. Zona taman tersusun melingkar: area kuliner dan kafe di sisi selatan, danau dan air mancur di tengah, Food Court 2 dan gerbang timur di sisi timur, serta jalur jogging, musala, dan gerbang utara di sisi utara. Masjid Al-Maleeq berada tidak jauh di utara gerbang ini.', 'Audio sambutan, ringkasan zona taman, dan rekomendasi rute sesuai jam kunjungan.', 'SETARA:POI:P01', 'google_maps', true, 'Gerbang utama di sisi Jl. Banten, titik awal menjelajah taman.', 'Wilujeng sumping di Kiara Artha Park! Aku Kia, teman jelajahmu. Kamu sekarang di gerbang barat, sisi Jalan Banten. Taman ini diresmikan tanggal tujuh belas Agustus dua ribu sembilan belas, dan sekarang jadi salah satu ruang publik favorit warga Bandung. Tata letaknya melingkar, lho. Di tengah ada danau dengan air mancur menari. Di sisi utara ada titik start jogging track dan musala. Di sisi timur ada Food Court 2, dan area kuliner utama di sisi selatan. Ikuti jalur pejalan kaki ke timur untuk sampai di lingkar taman. Nanti aku sapa lagi setiap kamu dekat spot seru. Oh iya, di tiap spot ada kuis dan misi kecil. Kumpulkan bintangnya, ya!', array['Peta ringkas zona taman', 'Titik kumpul rombongan', 'Akses ke Selter BOSEH, area parkir, dan Masjid Al-Maleeq']::text[], array['Foto papan peta di gerbang sebagai cadangan bila baterai menipis.', 'Sore hari (15.00–18.00) cocok untuk jalan santai sebelum pertunjukan air mancur.']::text[], array['pagi', 'siang', 'sore', 'malam']::text[], array['gerbang', 'pintu', 'masuk', 'jl banten', 'peta', 'tiket']::text[], 'gate', null, 'Google Maps: "Gerbang Barat Taman Kiara Artha"', 1)
insert into public.poi (id, name, short_name, category_id, zone, location, radius_m, description, trigger_response, qr_code, data_source, is_published, summary, narration, activities, tips, best_times, keywords, art, status_note, source_place, sort_order) values ('P02', 'Gerbang Area Parkir', 'Area Parkir', 'akses', 'Area parkir sisi barat laut, dekat gerbang utama', extensions.st_setsrid(extensions.st_makepoint(107.6411222, -6.9154692), 4326)::extensions.geography, 25, 'Area parkir utama berada di sisi barat laut taman, tidak jauh dari Jl. Banten. Dari gerbang parkir, pengunjung dapat berjalan ke selatan menuju Pintu Utama, atau ke timur menuju titik start jogging track, musala, dan toilet di sisi utara taman. Selter Sepeda BOSEH juga berada di dekat sini.', 'Notifikasi selamat datang, arah ke pintu utama, dan info fasilitas terdekat.', 'SETARA:POI:P02', 'google_maps', true, 'Area parkir utama; arah ke Pintu Utama dan fasilitas terdekat.', 'Halo, selamat datang! Kamu ada di gerbang area parkir, sisi barat laut taman. Mau ke Pintu Utama? Jalan saja sekitar sembilan puluh meter ke selatan. Kalau mau langsung olahraga, titik start jogging track ada di sebelah timur, dekat musala dan toilet. Selter sepeda BOSEH juga dekat dari sini. Sebelum jalan, ingat-ingat dulu lokasi kendaraanmu, ya. Itu misi pertamamu di sini!', array['Parkir mobil dan motor', 'Arah ke Pintu Utama (±90 m ke selatan)', 'Toilet terdekat di sisi utara taman']::text[], array['Catat blok parkir kendaraan Anda.', 'Akhir pekan sore hari biasanya ramai; datang sebelum pukul 16.00.']::text[], array['pagi', 'siang', 'sore', 'malam']::text[], array['parkir', 'mobil', 'motor', 'kendaraan', 'gerbang']::text[], 'parking', null, 'Google Maps: "Kiara Artha Parking Lot"', 2)
insert into public.poi (id, name, short_name, category_id, zone, location, radius_m, description, trigger_response, qr_code, data_source, is_published, summary, narration, activities, tips, best_times, keywords, art, status_note, source_place, sort_order) values ('P03', 'Danau & Air Mancur Menari', 'Air Mancur', 'atraksi', 'Danau buatan di area tengah taman', extensions.st_setsrid(extensions.st_makepoint(107.6422657, -6.9160874), 4326)::extensions.geography, 40, 'Danau di jantung taman ini adalah ikon Kiara Artha Park. Pada malam hari, air mancur menari tampil dengan permainan cahaya dan musik. Siang hingga sore, tepian danau menjadi tempat favorit untuk duduk santai, menikmati angin, dan memandangi patung Friendship Shake Hand di tepi utara.', 'Kartu informasi dan narasi; sore/malam menampilkan hitung mundur pertunjukan air mancur.', 'SETARA:POI:P03', 'google_maps', true, 'Ikon taman: danau dengan pertunjukan air mancur menari di malam hari.', 'Kamu sampai di tepi danau, jantung Kiara Artha Park! Di tengah danau inilah air mancur menari tampil setiap malam. Pertunjukannya biasanya mulai jam setengah tujuh malam sampai setengah sembilan, dengan tema berbeda tiap jam. Semburan airnya bergerak mengikuti musik dan disinari lampu warna-warni. Coba lihat ke tepi utara danau. Ada patung dua tangan yang berjabat, namanya Friendship Shake Hand, simbol persahabatan. Kalau kamu datang siang, nikmati angin di tepi danau dulu, lalu balik lagi saat matahari terbenam. Bisa temukan patungnya? Itu misimu!', array['Menonton pertunjukan air mancur menari (malam)', 'Duduk santai di tepi danau', 'Foto dengan latar air mancur']::text[], array['Datang 15 menit sebelum pertunjukan untuk mendapat posisi depan.', 'Akses menonton disebut termasuk dalam paket Kiara Pelangi Food Court Rp35.000 (Orami, 2024); konfirmasi di lokasi.']::text[], array['sore', 'malam']::text[], array['danau', 'air mancur', 'fountain', 'pertunjukan', 'malam', 'lampu', 'show']::text[], 'fountain', 'Jadwal pertunjukan dapat berubah; cek Instagram @kiaraarthapark.', 'Google Maps: "Dancing Fountain"', 3)
insert into public.poi (id, name, short_name, category_id, zone, location, radius_m, description, trigger_response, qr_code, data_source, is_published, summary, narration, activities, tips, best_times, keywords, art, status_note, source_place, sort_order) values ('P05', 'Spot Foto Ikonik: Taman Asia Afrika', 'Taman Asia Afrika', 'atraksi', 'Sisi selatan danau', extensions.st_setsrid(extensions.st_makepoint(107.6421607, -6.9166173), 4326)::extensions.geography, 25, 'Taman Asia Afrika di sisi selatan danau adalah spot foto paling ikonik di Kiara Artha Park, dengan latar danau dan air mancur menari. Namanya menggemakan Konferensi Asia Afrika 1955 yang membuat Bandung dikenal dunia.', 'Cerita singkat spot serta tips waktu dan sudut foto terbaik.', 'SETARA:POI:P05', 'google_maps', true, 'Spot foto utama dengan latar danau dan air mancur.', 'Wilujeng sumping di Taman Asia Afrika, spot foto paling ikonik di Kiara Artha Park! Namanya mengingatkan kita pada Konferensi Asia Afrika tahun seribu sembilan ratus lima puluh lima, waktu pemimpin dua puluh sembilan negara berkumpul di Gedung Merdeka, Bandung. Dari sini, danau dan air mancur menari kelihatan utuh. Untuk foto terbaik, menghadaplah ke utara. Pagi hari cahayanya lembut dari samping, malam hari air mancurnya warna-warni. Siapkan gaya terbaikmu, lalu simpan fotonya di Jurnal Kunjungan!', array['Foto dengan latar danau dan air mancur', 'Foto rombongan']::text[], array['Sudut terbaik: menghadap utara ke arah air mancur.', 'Foto malam: aktifkan mode malam dan tunggu pertunjukan air mancur dimulai.']::text[], array['pagi', 'sore', 'malam']::text[], array['foto', 'ikonik', 'asia afrika', 'spot foto', 'instagram', 'selfie']::text[], 'photo', null, 'Google Maps: "Taman Asia Afrika - Kiara Artha Park"', 4)
insert into public.poi (id, name, short_name, category_id, zone, location, radius_m, description, trigger_response, qr_code, data_source, is_published, summary, narration, activities, tips, best_times, keywords, art, status_note, source_place, sort_order) values ('P06', 'Titik Start Jogging Track', 'Start Jogging', 'wellness', 'Awal jalur jogging, sisi utara taman', extensions.st_setsrid(extensions.st_makepoint(107.6417524, -6.9152676), 4326)::extensions.geography, 25, 'Titik awal jalur jogging berada di sisi utara taman. Jalur ini mengikuti lingkar Jl. Kiara Artha yang mengelilingi danau, sekitar 750 meter per putaran, cocok untuk jalan cepat, jogging, maupun bersepeda santai.', 'Tawaran memulai Wellness Trail, info panjang rute, dan tips pemanasan.', 'SETARA:POI:P06', 'google_maps', true, 'Awal jalur jogging lingkar taman; mulai Wellness Trail dari sini.', 'Kamu di titik start jogging track! Jalur di depanmu mengikuti lingkar Jalan Kiara Artha yang mengelilingi danau, kira-kira tujuh ratus lima puluh meter satu putaran. Sebelum mulai, yuk pemanasan tiga sampai lima menit: putar pergelangan kaki, ayunkan lengan, lalu jalan di tempat. Mau dipandu? Mulai Wellness Trail dari menu Trail, nanti aku temani di setiap checkpoint dan catat jarak serta durasimu. Ayo, pemanasan bareng aku dulu!', array['Memulai Wellness Trail', 'Jogging lingkar taman (±750 m per putaran)', 'Pemanasan sebelum berlari']::text[], array['Lakukan pemanasan 3–5 menit sebelum berlari.', 'Pagi pukul 06.00–09.00 udara paling segar dan jalur belum ramai.']::text[], array['pagi', 'sore']::text[], array['jogging', 'lari', 'olahraga', 'track', 'trail', 'jalan pagi', 'wellness']::text[], 'jogging', null, 'Google Maps: "Jogging Track Kiara Artha Park"', 5)
insert into public.poi (id, name, short_name, category_id, zone, location, radius_m, description, trigger_response, qr_code, data_source, is_published, summary, narration, activities, tips, best_times, keywords, art, status_note, source_place, sort_order) values ('P07', 'Selter Sepeda BOSEH', 'Selter BOSEH', 'wellness', 'Sisi barat taman, dekat area parkir', extensions.st_setsrid(extensions.st_makepoint(107.6408092, -6.915669), 4326)::extensions.geography, 20, 'Selter Bike on the Street Everybody Happy (BOSEH) di sisi barat taman. Pengunjung dapat menyewa sepeda untuk berkeliling lingkar taman maupun menjelajah Bandung. Di dalam taman juga tersedia persewaan sepeda dan skuter listrik swasta.', 'Info cara sewa sepeda/skuter, tarif dan jam operasional, serta rute bersepeda.', 'SETARA:POI:P07', 'google_maps', true, 'Sewa sepeda BOSEH untuk berkeliling taman dan kota.', 'Ini Selter Sepeda BOSEH, singkatan dari Bike on the Street Everybody Happy, program sepeda sewa Pemerintah Kota Bandung. Cara sewanya gampang: daftar pakai kartu identitas di petugas atau aplikasi BOSEH, lalu pilih sepeda yang tersedia. Tarif resminya mulai seribu rupiah untuk jam pertama. Di dalam taman juga ada sewa sepeda dan skuter listrik, sekitar tiga puluh sampai empat puluh ribu rupiah. Rute favorit: lingkar Jalan Kiara Artha mengelilingi danau. Tetap utamakan pejalan kaki, ya!', array['Sewa sepeda BOSEH', 'Sewa sepeda/skuter listrik di dalam taman', 'Bersepeda di lingkar taman']::text[], array['Siapkan kartu identitas untuk registrasi.', 'Gunakan jalur lingkar dan utamakan pejalan kaki.']::text[], array['pagi', 'sore']::text[], array['sepeda', 'boseh', 'skuter', 'sewa', 'bike', 'bersepeda']::text[], 'bike', 'Jam layanan mengacu pada jam booth BOSEH Pemkot Bandung; konfirmasi saat survei.', 'Google Maps: "Stasiun Boseh Kiara Artha Park"', 6)
insert into public.poi (id, name, short_name, category_id, zone, location, radius_m, description, trigger_response, qr_code, data_source, is_published, summary, narration, activities, tips, best_times, keywords, art, status_note, source_place, sort_order) values ('P08', 'Area Kuliner / Food Court', 'Area Kuliner', 'kuliner', 'Kawasan Kiara Pelangi, sisi selatan taman', extensions.st_setsrid(extensions.st_makepoint(107.641775, -6.9170555), 4326)::extensions.geography, 30, 'Kawasan kuliner di sisi selatan taman dengan beragam tenant makanan dan minuman. Kiara Pelangi Food Court menjadi pusatnya, berdekatan dengan kafe seperti Ludo Sports Kitchen and Coffee dan Monday Co. Pilihan tepat untuk makan bersama sebelum menonton air mancur menari.', 'Info tenant dan jam buka; jika belum buka, tampilkan jam buka dan alternatif terdekat.', 'SETARA:POI:P08', 'google_maps', true, 'Kiara Pelangi Food Court dan deretan kafe di sisi selatan.', 'Kamu tiba di Area Kuliner! Di kawasan Kiara Pelangi ini ada food court dengan banyak tenant, dari makanan berat sampai jajanan dan minuman segar. Di sekitarnya ada kafe populer seperti Ludo Sports Kitchen and Coffee dan Monday Co. Menariknya, paket Kiara Pelangi Food Court disebut sudah termasuk akses menonton air mancur menari, jadi kamu bisa makan malam sambil menunggu pertunjukan. Jam buka tiap tenant beda-beda, cek papan info di lokasi, ya. Selamat makan, dan jangan lupa foto menu favoritmu!', array['Makan dan minum di food court', 'Nongkrong di kafe sekitar', 'Membeli paket makan + akses air mancur']::text[], array['Jam makan malam akhir pekan ramai; pesan lebih awal sebelum pertunjukan air mancur.', 'Jam buka tenant bervariasi.']::text[], array['siang', 'sore', 'malam']::text[], array['makan', 'kuliner', 'food court', 'kiara pelangi', 'restoran', 'minum', 'jajan']::text[], 'food', 'Jam buka tenant bervariasi; konfirmasi saat survei.', 'Google Maps: "Pelangi Graha Park"', 7)
insert into public.poi (id, name, short_name, category_id, zone, location, radius_m, description, trigger_response, qr_code, data_source, is_published, summary, narration, activities, tips, best_times, keywords, art, status_note, source_place, sort_order) values ('P09', 'Area Kafe & Lapangan Padel', 'Kafe & Padel', 'kuliner', 'Kawasan kafe dan lapangan padel, sisi utara', extensions.st_setsrid(extensions.st_makepoint(107.6422184, -6.9149564), 4326)::extensions.geography, 30, 'Kawasan kafe dan lapangan padel di sisi utara taman. Padel, olahraga raket perpaduan tenis dan squash, sedang populer di Bandung, dan Padel Co. menyediakan lapangan semi-outdoor di sini. Kafe di sekitarnya cocok untuk beristirahat setelah berolahraga.', 'Info kafe, lapangan padel, jam operasional, dan aktivitas yang tersedia.', 'SETARA:POI:P09', 'google_maps', true, 'Kafe dan lapangan padel semi-outdoor di sisi utara taman.', 'Kamu ada di Area Kafe dan Lapangan Padel, sisi utara taman. Tahu nggak, padel lahir di Meksiko tahun seribu sembilan ratus enam puluh sembilan? Mainnya mirip tenis, tapi lapangannya lebih kecil, dikelilingi dinding kaca, dan bolanya boleh memantul ke dinding. Lapangan semi-outdoor di sini bisa dipesan langsung ke pengelola. Kalau cuma mau santai, kafe di sekitarnya pas untuk minum sambil nonton pertandingan. Coba tonton satu reli sampai selesai, deh!', array['Menonton atau bermain padel', 'Bersantai di kafe', 'Istirahat setelah jogging']::text[], array['Pemesanan lapangan dilakukan langsung ke pengelola; SETARA tidak menyediakan reservasi.', 'Gunakan sepatu bersol rata untuk bermain padel.']::text[], array['pagi', 'sore', 'malam']::text[], array['padel', 'kafe', 'cafe', 'kopi', 'olahraga', 'raket', 'nongkrong']::text[], 'padel', 'Jam operasional perlu dikonfirmasi ke pengelola saat survei.', 'Google Maps: "Padel Co. Semi Outdoor"', 8)
insert into public.poi (id, name, short_name, category_id, zone, location, radius_m, description, trigger_response, qr_code, data_source, is_published, summary, narration, activities, tips, best_times, keywords, art, status_note, source_place, sort_order) values ('P11', 'Zona Relaksasi / Spot Teduh', 'Zona Teduh', 'wellness', 'Kanopi pepohonan di sisi timur danau', extensions.st_setsrid(extensions.st_makepoint(107.643112, -6.91593), 4326)::extensions.geography, 20, 'Area teduh di bawah kanopi pepohonan rindang di sisi timur danau. Tempat ideal untuk berhenti sejenak, mengatur napas, dan melakukan peregangan ringan, sekaligus menjadi checkpoint Wellness Trail.', 'Tawaran audio relaksasi 1–2 menit; menjadi checkpoint Wellness Trail.', 'SETARA:POI:P11', 'google_maps', true, 'Area duduk teduh untuk relaksasi napas dan peregangan ringan.', 'Selamat datang di Zona Teduh, di bawah kanopi pepohonan sisi timur danau. Yuk, berhenti sebentar bareng aku. Berdiri dengan nyaman atau duduk di bangku terdekat. Tarik napas pelan lewat hidung, empat hitungan. Tahan sebentar. Lalu hembuskan pelan lewat mulut, enam hitungan. Ulangi tiga kali. Sekarang angkat kedua bahu ke arah telinga, tahan, lalu lepaskan. Putar leher pelan ke kiri dan ke kanan. Rasakan udara yang lebih sejuk di bawah pohon ini. Kalau sudah siap, lanjutkan perjalananmu dengan langkah yang lebih ringan.', array['Audio relaksasi 1–2 menit', 'Peregangan ringan', 'Checkpoint Wellness Trail']::text[], array['Lepaskan earphone sejenak dan dengarkan suara di sekitar Anda.', 'Minum air setelah berjalan atau berlari.']::text[], array['pagi', 'siang', 'sore']::text[], array['teduh', 'relaksasi', 'istirahat', 'napas', 'peregangan', 'pohon', 'duduk']::text[], 'shade', 'Titik ditentukan dari citra satelit Google Maps; validasi saat survei lapangan.', 'Google Maps (citra satelit): titik di bawah kanopi pohon, timur danau', 9)
insert into public.poi (id, name, short_name, category_id, zone, location, radius_m, description, trigger_response, qr_code, data_source, is_published, summary, narration, activities, tips, best_times, keywords, art, status_note, source_place, sort_order) values ('P12', 'Musala & Toilet', 'Musala & Toilet', 'fasilitas', 'Fasilitas umum utama, sisi utara taman', extensions.st_setsrid(extensions.st_makepoint(107.6421597, -6.9151658), 4326)::extensions.geography, 20, 'Fasilitas umum utama di sisi utara taman: musala, tempat wudu, dan toilet. Lokasinya dekat Layana Hall dan titik start jogging track, sehingga mudah dijangkau sebelum atau sesudah berolahraga.', 'Info fasilitas dan arah; tampil sebagai hasil cepat pada filter Fasilitas.', 'SETARA:POI:P12', 'google_maps', true, 'Musala, tempat wudu, dan toilet umum di sisi utara taman.', 'Kamu di area Musala dan Toilet, fasilitas umum utama di sisi utara taman. Di sini ada musala, tempat wudu, dan toilet umum. Menjelang magrib musala biasanya ramai, jadi datang beberapa menit lebih awal, ya. Simpan alas kaki di rak yang tersedia dan bantu jaga kebersihan bareng-bareng. Setelah ini, kamu bisa lanjut ke titik start jogging track di sebelah barat, atau ke danau dan air mancur di selatan. Hatur nuhun sudah ikut menjaga taman!', array['Salat', 'Wudu', 'Toilet umum']::text[], array['Menjelang magrib musala biasanya ramai; datang beberapa menit lebih awal.', 'Jaga kebersihan dan simpan alas kaki di rak yang tersedia.']::text[], array['pagi', 'siang', 'sore', 'malam']::text[], array['musala', 'mushola', 'salat', 'sholat', 'toilet', 'wc', 'kamar mandi', 'wudu']::text[], 'musala', null, 'Google Maps: "Mushalla Kiara Artha Park"', 10)
insert into public.poi (id, name, short_name, category_id, zone, location, radius_m, description, trigger_response, qr_code, data_source, is_published, summary, narration, activities, tips, best_times, keywords, art, status_note, source_place, sort_order) values ('P13', 'Gerbang Utara Kiara Artha Park', 'Gerbang Utara', 'akses', 'Sisi Jl. Jakarta, ujung Jl. Kiara Artha Utara', extensions.st_setsrid(extensions.st_makepoint(107.64128, -6.9142), 4326)::extensions.geography, 25, 'Gerbang utara menghubungkan Jl. Jakarta dengan taman melalui Jl. Kiara Artha Utara. Pengunjung yang turun di halte Gerbang Utara bisa berjalan lurus ke selatan sekitar 100 meter hingga tiba di lingkar Jl. Kiara Artha, dekat lapangan padel, titik start jogging track, serta musala dan toilet.', 'Sambutan, arah ke lingkar taman, dan spot terdekat dari sisi utara.', 'SETARA:POI:P13', 'google_maps', true, 'Pintu masuk dari Jl. Jakarta lewat Jl. Kiara Artha Utara, dekat halte bus.', 'Halo, selamat datang dari sisi utara! Kamu di Gerbang Utara, dekat halte bus di Jalan Jakarta. Jalan lurus saja ke selatan lewat Jalan Kiara Artha Utara, kira-kira seratus meter, sampai ketemu lingkar taman. Di sana ada lapangan padel, titik start jogging track, juga musala dan toilet. Hati-hati menyeberang, ya, Jalan Jakarta ramai. Begitu sampai di lingkar taman, aku sapa lagi. Misi pertamamu: hitung berapa langkah sampai ke lingkar taman!', array['Masuk dari arah Jl. Jakarta', 'Turun dari bus di halte Gerbang Utara', 'Akses cepat ke jogging track dan area padel']::text[], array['Menyeberang Jl. Jakarta lewat zebra cross dan tetap waspada; lalu lintasnya ramai.', 'Lanjut lurus ke selatan untuk tiba di lingkar taman.']::text[], array['pagi', 'siang', 'sore', 'malam']::text[], array['gerbang', 'gerbang utara', 'pintu', 'masuk', 'jl jakarta', 'halte', 'bus', 'kiara artha utara']::text[], 'gate', 'Titik gerbang ditentukan dari peta; validasi saat survei lapangan.', 'OpenStreetMap: halte "Gerbang Utara Kiara Artha Park", Jl. Jakarta; Google Maps: Jl. Kiara Artha Utara', 11)
insert into public.poi (id, name, short_name, category_id, zone, location, radius_m, description, trigger_response, qr_code, data_source, is_published, summary, narration, activities, tips, best_times, keywords, art, status_note, source_place, sort_order) values ('P14', 'Gerbang Timur Kiara Artha Park', 'Gerbang Timur', 'akses', 'Sisi Jl. H. Ibrahim Adjie (Kiaracondong)', extensions.st_setsrid(extensions.st_makepoint(107.6437, -6.91615), 4326)::extensions.geography, 25, 'Gerbang timur berada di sisi Jl. H. Ibrahim Adjie (Kiaracondong), terhubung ke lingkar taman lewat dua ruas Jl. Kiara Artha. Tepat di sebelah selatannya ada Food Court 2 dengan deretan kafe dan resto, sementara Zona Teduh dan danau berada sekitar 60–150 meter ke arah barat.', 'Sambutan, arah ke danau, dan info Food Court 2 di sebelahnya.', 'SETARA:POI:P14', 'google_maps', true, 'Pintu masuk dari Jl. Ibrahim Adjie, tepat di samping Food Court 2.', 'Wilujeng sumping dari sisi timur! Kamu di Gerbang Timur, menghadap Jalan Ibrahim Adjie, arah Kiaracondong. Tepat di sebelah selatanmu ada Food Court 2, deretan kafe dan resto kayak Steak Ranjang dan Pang Waffle. Kalau lurus ke barat, kamu ketemu Zona Teduh lalu danau dengan air mancur menari. Malam hari, pertunjukannya mulai jam setengah tujuh. Oh iya, halte bus di depan gerbang ini namanya juga Gerbang Timur, jadi gampang dijadikan patokan pulang. Yuk, masuk pelan-pelan dan nikmati tamannya!', array['Masuk dari arah Jl. Ibrahim Adjie', 'Turun dari bus di halte Gerbang Timur', 'Akses cepat ke Food Court 2']::text[], array['Jl. Ibrahim Adjie padat pada jam sibuk; menyeberanglah di titik penyeberangan.', 'Belok kiri (selatan) untuk Food Court 2, lurus ke barat untuk danau.']::text[], array['pagi', 'siang', 'sore', 'malam']::text[], array['gerbang', 'gerbang timur', 'pintu', 'masuk', 'ibrahim adjie', 'kiaracondong', 'halte', 'bus']::text[], 'gate', 'Titik gerbang ditentukan dari peta; validasi saat survei lapangan.', 'OpenStreetMap: halte "Gerbang Timur Kiara Artha Park", Jl. H. Ibrahim Adjie', 12)
insert into public.poi (id, name, short_name, category_id, zone, location, radius_m, description, trigger_response, qr_code, data_source, is_published, summary, narration, activities, tips, best_times, keywords, art, status_note, source_place, sort_order) values ('P15', 'Food Court 2: Deretan Kafe Sisi Timur', 'Food Court 2', 'kuliner', 'Bangunan sisi timur, antara lingkar taman dan Jl. Ibrahim Adjie', extensions.st_setsrid(extensions.st_makepoint(107.64351, -6.91649), 4326)::extensions.geography, 30, 'Food court kedua berada di bangunan memanjang sisi timur taman, di antara lingkar Jl. Kiara Artha dan Jl. Ibrahim Adjie. Deretan tenannya dari utara ke selatan antara lain Steak Ranjang, Siloka, Pang Waffle, dan RD Coffee & Eatery: pilihan steak, jajanan manis, sampai kopi. Cocok untuk makan setelah jogging atau sambil menunggu air mancur menari di malam hari.', 'Info tenan, jam buka, dan arah ke danau setelah makan.', 'SETARA:POI:P15', 'google_maps', true, 'Food court kedua: Steak Ranjang, Siloka, Pang Waffle, dan RD Coffee & Eatery.', 'Kamu tiba di Food Court 2, sisi timur taman! Di bangunan memanjang ini ada Steak Ranjang, Siloka, Pang Waffle, dan RD Coffee and Eatery. Mau makan berat, jajan manis, atau sekadar ngopi, semuanya ada. Jam buka tiap tenan beda-beda, jadi cek papan di depannya, ya. Habis makan, jalan ke barat sekitar seratus empat puluh meter untuk sampai di danau. Pas banget kalau mau nonton air mancur menari malam nanti!', array['Makan steak, waffle, atau jajanan', 'Ngopi di kafe', 'Istirahat setelah jogging']::text[], array['Jam buka tiap tenan berbeda; cek papan di depan tenan.', 'Akhir pekan malam ramai; datang sebelum pukul 18.00 bila ingin menonton air mancur setelah makan.']::text[], array['siang', 'sore', 'malam']::text[], array['makan', 'kuliner', 'food court', 'food court 2', 'steak', 'steak ranjang', 'siloka', 'waffle', 'pang waffle', 'rd coffee', 'kopi', 'kafe', 'jajan']::text[], 'food', 'Jam buka tenan bervariasi; konfirmasi saat survei.', 'OpenStreetMap: Steak Ranjang, Siloka, Pang Waffle, RD Coffee & Eatery (Jl. H. Ibrahim Adjie)', 13)
insert into public.poi (id, name, short_name, category_id, zone, location, radius_m, description, trigger_response, qr_code, data_source, is_published, summary, narration, activities, tips, best_times, keywords, art, status_note, source_place, sort_order) values ('P16', 'Masjid Al-Maleeq', 'Masjid Al-Maleeq', 'fasilitas', 'Sisi barat, di pojok deretan toko dekat Jl. Banten', extensions.st_setsrid(extensions.st_makepoint(107.64066, -6.916), 4326)::extensions.geography, 20, 'Masjid Al-Maleeq berada di sisi barat kawasan Kiara Artha, di pojok deretan toko dekat Jl. Banten dan tidak jauh dari Pintu Utama. Pengunjung yang masuk dari gerbang barat atau area parkir bisa salat di sini; untuk sisi utara taman tersedia juga musala dan toilet dekat Layana Hall.', 'Info masjid dan arah; tampil sebagai hasil cepat saat mencari masjid/musala.', 'SETARA:POI:P16', 'google_maps', true, 'Masjid di sisi barat taman, dekat Jl. Banten dan Pintu Utama.', 'Assalamualaikum! Kamu di dekat Masjid Al-Maleeq, di sisi barat kawasan Kiara Artha, dekat Jalan Banten. Kalau sudah masuk waktu salat, kamu bisa beribadah di sini sebelum lanjut menjelajah. Simpan alas kaki di tempatnya dan jaga kebersihan, ya. Kalau sedang di sisi utara taman, ada juga musala dekat Layana Hall. Menjelang magrib biasanya ramai, jadi datang sedikit lebih awal. Setelah salat, Pintu Utama dan Selter BOSEH ada tidak jauh di sebelah selatan dan timur, siap jadi titik awal jelajahmu berikutnya.', array['Salat berjamaah', 'Wudu', 'Istirahat sejenak']::text[], array['Menjelang magrib biasanya ramai; datang beberapa menit lebih awal.', 'Simpan alas kaki di tempat yang disediakan dan jaga kebersihan.']::text[], array['pagi', 'siang', 'sore', 'malam']::text[], array['masjid', 'mesjid', 'al maleeq', 'al-maleeq', 'salat', 'sholat', 'shalat', 'jumat', 'wudu', 'ibadah']::text[], 'musala', 'Koordinat diperkirakan dari Google Maps (belum ada di OpenStreetMap); validasi saat survei lapangan.', 'Google Maps: "Masjid Al-Maleeq" (diakses 24 Nov 2026)', 14)
insert into public.poi_category (poi_id, category_id) values ('P01', 'akses'), ('P02', 'akses'), ('P03', 'atraksi'), ('P05', 'atraksi'), ('P06', 'wellness'), ('P07', 'wellness'), ('P08', 'kuliner'), ('P09', 'kuliner'), ('P09', 'wellness'), ('P11', 'wellness'), ('P12', 'fasilitas'), ('P13', 'akses'), ('P14', 'akses'), ('P15', 'kuliner'), ('P16', 'fasilitas');
insert into public.trivia (poi_id, content, source_reference, is_verified) values
  ('P01', 'Kiara Artha Park diresmikan pada 17 Agustus 2019, bertepatan dengan HUT ke-74 Republik Indonesia.', 'Orami (30 Sep 2024); Republika (24 Agu 2019)', true),
  ('P01', 'Taman ini terletak di antara flyover Antapani dan flyover Kiaracondong, di Kelurahan Kebonwaru, Kecamatan Batununggal.', 'Orami (2024); Republika (2019)', true),
  ('P02', 'Lokasi taman yang berada di antara dua flyover besar Bandung timur membuatnya mudah dijangkau dari arah Antapani maupun Kiaracondong.', 'Orami (2024); Republika (2019)', true),
  ('P02', 'Tiket masuk taman tercatat Rp10.000 per orang, baik hari kerja maupun akhir pekan (detikJabar, 2024). Cek kembali di loket karena harga dapat berubah.', 'detikJabar (Mar 2024)', true),
  ('P03', 'Pertunjukan air mancur menari umumnya digelar mulai pukul 18.30 hingga 20.30, dengan pertunjukan berbeda setiap jamnya (Orami, 2024).', 'Orami (30 Sep 2024)', true),
  ('P03', 'Patung Friendship Shake Hand di tepi utara danau menggambarkan jabat tangan persahabatan, sejalan dengan semangat Asia Afrika kota Bandung.', 'Google Maps: Friendship Shake Hand Sculpture', true),
  ('P05', 'Konferensi Asia Afrika digelar di Gedung Merdeka, Bandung, pada 18–24 April 1955 dan dihadiri 29 negara.', 'Sejarah KAA 1955 (Museum KAA) — perlu dicek tim', false),
  ('P05', 'Dari titik ini air mancur menari terlihat utuh, sudut favorit untuk foto malam.', 'Pengamatan peta Google Maps', true),
  ('P06', 'Area jogging dan bersepeda di Kiara Artha Park disebut mencapai sekitar 2,6 hektare (Orami, 2024).', 'Orami (30 Sep 2024)', true),
  ('P06', 'Kiara Artha Park pernah menjadi tuan rumah acara lari Pocari Run 2025.', 'Asia Property Awards — profil Kiara Artha Park', true),
  ('P07', 'BOSEH adalah program sepeda sewa Pemerintah Kota Bandung; tarif resmi tercatat Rp1.000 untuk jam pertama dan Rp2.000 untuk jam berikutnya.', 'Pemkot Bandung — BOSEH', true),
  ('P07', 'Persewaan sepeda dan skuter listrik di dalam taman bertarif Rp30.000 pada hari kerja dan Rp40.000 pada akhir pekan (detikJabar, 2024).', 'detikJabar (Mar 2024)', true),
  ('P08', 'Paket Kiara Pelangi Food Court seharga Rp35.000 disebut sudah termasuk akses menonton air mancur menari (Orami, 2024).', 'Orami (30 Sep 2024)', true),
  ('P08', 'Ludo Sports Kitchen and Coffee di dekat area ini memiliki lebih dari seribu ulasan di Google Maps dengan rating 4,8.', 'Google Maps: Ludo Sports Kitchen and Coffee (16 Nov 2026)', true),
  ('P09', 'Padel lahir di Acapulco, Meksiko, pada 1969 dan dimainkan berpasangan di lapangan berdinding kaca.', 'Pengetahuan umum olahraga padel — perlu dicek tim', false),
  ('P09', 'Dalam padel, bola boleh memantul ke dinding sebelum dipukul kembali, berbeda dengan tenis.', 'Pengetahuan umum olahraga padel — perlu dicek tim', false),
  ('P11', 'Kanopi pohon dapat membuat udara di bawahnya terasa lebih sejuk dibanding area terbuka di siang hari.', 'Pengetahuan umum kesehatan — perlu dicek tim', false),
  ('P11', 'Menghembuskan napas lebih panjang daripada menarik napas membantu menenangkan detak jantung setelah berjalan.', 'Pengetahuan umum kesehatan — perlu dicek tim', false),
  ('P12', 'Musala ini tercatat di Google Maps sebagai "Mushalla Kiara Artha Park", berdekatan dengan Layana Hall.', 'Google Maps: Mushalla Kiara Artha Park', true),
  ('P12', 'Toilet umum lain juga tersedia di sekitar area parkir sisi barat laut taman.', 'Google Maps: "Kamar Cai" dekat parkir — perlu dicek tim', false),
  ('P13', 'Halte bus di depan gerbang ini bernama "Gerbang Utara Kiara Artha Park", sehingga mudah dijadikan patokan saat naik kendaraan umum.', 'OpenStreetMap: halte Gerbang Utara Kiara Artha Park (24 Nov 2026)', true),
  ('P13', 'Dari gerbang ini, titik start jogging track hanya sekitar 130 meter ke arah tenggara.', 'Hitungan jarak koordinat peta', true),
  ('P14', 'Halte bus di depan gerbang ini bernama "Gerbang Timur Kiara Artha Park" dan berada di jalur Jl. Ibrahim Adjie yang ramai.', 'OpenStreetMap: halte Gerbang Timur Kiara Artha Park (24 Nov 2026)', true),
  ('P14', 'Kiara Artha Park terletak di antara flyover Antapani dan flyover Kiaracondong; gerbang timur adalah sisi yang menghadap Kiaracondong.', 'Orami (2024); Republika (2019)', true),
  ('P15', 'Urutan tenan dari utara ke selatan: Steak Ranjang, Siloka, Pang Waffle, lalu RD Coffee & Eatery (OpenStreetMap, 2026).', 'OpenStreetMap: tenan Jl. H. Ibrahim Adjie (24 Nov 2026)', true),
  ('P15', 'Dari sini danau dan air mancur menari hanya sekitar 140 meter ke arah barat.', 'Hitungan jarak koordinat peta', true),
  ('P16', 'Google Maps mencatat lokasi masjid ini berada di pojok deretan bangunan, dekat Jl. Banten.', 'Google Maps: Masjid Al-Maleeq (24 Nov 2026)', true),
  ('P16', 'Selain masjid ini, Kiara Artha Park juga punya musala di sisi utara, dekat Layana Hall dan titik start jogging track.', 'Google Maps: Mushalla Kiara Artha Park', true);
