insert into public.wellness_trail (id, name, subtitle, description, level, distance_m, est_minutes, best_times, color, path, sort_order) values ('T01', 'Rute Santai Kelilingi Danau', 'Jalan santai dengan peregangan dan latihan napas', 'Rute jalan kaki santai mengelilingi danau melewati musala, zona teduh, dan Taman Asia Afrika. Setiap checkpoint memutar panduan audio berisi info spot dan ajakan peregangan atau latihan napas.', 'Santai', 670, 15, array['pagi', 'sore']::text[], '#3f9e8e', '[[-6.915268,107.641752],[-6.915232,107.641795],[-6.915206,107.641834],[-6.915188,107.641871],[-6.915177,107.641906],[-6.91517,107.641941],[-6.915168,107.641977],[-6.915167,107.642016],[-6.915168,107.642058],[-6.915168,107.642106],[-6.915166,107.64216],[-6.91516,107.642223],[-6.915152,107.642295],[-6.915143,107.642374],[-6.915135,107.642457],[-6.915129,107.642541],[-6.915127,107.642625],[-6.915131,107.642705],[-6.915143,107.64278],[-6.915164,107.642845],[-6.915196,107.642899],[-6.915242,107.642944],[-6.9153,107.642983],[-6.91537,107.643016],[-6.915447,107.643044],[-6.915529,107.643067],[-6.915614,107.643086],[-6.9157,107.643099],[-6.915782,107.643108],[-6.91586,107.643112],[-6.91593,107.643112],[-6.915996,107.643108],[-6.916062,107.643099],[-6.916127,107.643085],[-6.916191,107.643066],[-6.916253,107.643043],[-6.916312,107.643016],[-6.916367,107.642983],[-6.916417,107.642947],[-6.916461,107.642906],[-6.916499,107.64286],[-6.916528,107.642807],[-6.916547,107.642744],[-6.916558,107.642674],[-6.916564,107.642598],[-6.916567,107.642519],[-6.916569,107.642439],[-6.916573,107.642362],[-6.91658,107.642288],[-6.916595,107.64222],[-6.916617,107.642161],[-6.916655,107.64211],[-6.916709,107.642066],[-6.916773,107.642026],[-6.916842,107.64199],[-6.916911,107.641957],[-6.916974,107.641924],[-6.917025,107.641891],[-6.91706,107.641856],[-6.917072,107.641818],[-6.917055,107.641775],[-6.917007,107.641724],[-6.916931,107.641663],[-6.916832,107.641597],[-6.916716,107.641527],[-6.916588,107.641459],[-6.916455,107.641395],[-6.916321,107.64134],[-6.916193,107.641295],[-6.916077,107.641265],[-6.915977,107.641254],[-6.915888,107.641263],[-6.915802,107.64129],[-6.915718,107.641331],[-6.915637,107.641384],[-6.915561,107.641445],[-6.91549,107.641511],[-6.915424,107.641577],[-6.915365,107.641642],[-6.915312,107.641702],[-6.915268,107.641752]]'::jsonb, 1);
insert into public.trail_checkpoint (trail_id, seq, name, poi_id, location, radius_m, exercise, coaching) values
  ('T01', 1, 'Titik Start Jogging Track', 'P06', extensions.st_setsrid(extensions.st_makepoint(107.6417524, -6.9152676), 4326)::extensions.geography, 25, 'Pemanasan 1 menit', 'Checkpoint satu, titik start. Yuk pemanasan! Putar pergelangan kaki kanan dan kiri masing-masing lima kali, lalu ayunkan kedua lengan ke depan dan ke belakang. Setelah itu, jalan santai ke timur menuju musala.'),
  ('T01', 2, 'Musala & Layana Hall', 'P12', extensions.st_setsrid(extensions.st_makepoint(107.6421597, -6.9151658), 4326)::extensions.geography, 20, 'Cek hidrasi', 'Checkpoint dua, sisi utara taman. Di sini ada musala dan toilet. Kalau haus, minum beberapa teguk air. Jaga postur: bahu rileks, pandangan ke depan. Lanjut ke timur menuju Zona Teduh.'),
  ('T01', 3, 'Zona Teduh', 'P11', extensions.st_setsrid(extensions.st_makepoint(107.643112, -6.91593), 4326)::extensions.geography, 20, 'Peregangan ringan 1 menit', 'Checkpoint tiga, Zona Teduh. Saatnya peregangan ringan satu menit. Tarik lengan kanan menyilang ke depan dada, tahan sepuluh hitungan, lalu ganti lengan kiri. Kemudian tarik napas empat hitungan dan hembuskan enam hitungan. Ulangi tiga kali.'),
  ('T01', 4, 'Taman Asia Afrika', 'P05', extensions.st_setsrid(extensions.st_makepoint(107.6421607, -6.9166173), 4326)::extensions.geography, 25, 'Latihan napas 4-6', 'Checkpoint empat, Taman Asia Afrika. Pandang danau dan air mancur di utara. Tarik napas dalam empat hitungan, hembuskan enam hitungan. Rasakan langkahmu jadi lebih ringan. Lanjut ke barat lalu ke utara, kembali ke titik start.'),
  ('T01', 5, 'Finish: Titik Start', 'P06', extensions.st_setsrid(extensions.st_makepoint(107.6417524, -6.9152676), 4326)::extensions.geography, 25, 'Pendinginan', 'Hore, kamu menyelesaikan Rute Santai Kelilingi Danau! Yuk pendinginan: tarik tumit ke arah bokong untuk meregangkan paha depan, tahan lima belas hitungan untuk tiap kaki. Jangan lupa minum air, ya.');
insert into public.wellness_trail (id, name, subtitle, description, level, distance_m, est_minutes, best_times, color, path, sort_order) values ('T02', 'Jogging Lingkar Kiara Artha', 'Satu putaran jogging di lingkar Jl. Kiara Artha', 'Rute jogging mengikuti lingkar Jl. Kiara Artha yang mengelilingi taman. Panduan audio di tiap sisi taman membantu menjaga ritme langkah dan napas. Ulangi untuk menambah jarak.', 'Sedang', 760, 10, array['pagi', 'sore']::text[], '#ee7b5b', '[[-6.915208,107.641662],[-6.915149,107.641736],[-6.915098,107.641814],[-6.915055,107.641896],[-6.915019,107.64198],[-6.914993,107.642066],[-6.914974,107.642154],[-6.914965,107.642242],[-6.914964,107.642331],[-6.914972,107.642419],[-6.914988,107.642506],[-6.915014,107.642591],[-6.915047,107.642673],[-6.915089,107.642753],[-6.915139,107.642828],[-6.915196,107.642899],[-6.91526,107.642966],[-6.91533,107.643027],[-6.915407,107.643082],[-6.915489,107.64313],[-6.915576,107.643173],[-6.915667,107.643208],[-6.915761,107.643236],[-6.915858,107.643256],[-6.915957,107.643269],[-6.916058,107.643274],[-6.916159,107.643272],[-6.916259,107.643262],[-6.916358,107.643244],[-6.916456,107.643218],[-6.916551,107.643186],[-6.916643,107.643146],[-6.91673,107.643099],[-6.916813,107.643047],[-6.916891,107.642988],[-6.916963,107.642923],[-6.917028,107.642854],[-6.917087,107.64278],[-6.917138,107.642702],[-6.917181,107.64262],[-6.917217,107.642536],[-6.917243,107.64245],[-6.917262,107.642362],[-6.917271,107.642274],[-6.917272,107.642185],[-6.917264,107.642097],[-6.917248,107.64201],[-6.917222,107.641925],[-6.917189,107.641843],[-6.917147,107.641763],[-6.917097,107.641688],[-6.91704,107.641617],[-6.916976,107.64155],[-6.916906,107.641489],[-6.916829,107.641434],[-6.916747,107.641386],[-6.91666,107.641343],[-6.916569,107.641308],[-6.916475,107.64128],[-6.916378,107.64126],[-6.916279,107.641247],[-6.916178,107.641242],[-6.916077,107.641244],[-6.915977,107.641254],[-6.915878,107.641272],[-6.91578,107.641298],[-6.915685,107.64133],[-6.915593,107.64137],[-6.915506,107.641417],[-6.915423,107.641469],[-6.915345,107.641528],[-6.915273,107.641593],[-6.915208,107.641662]]'::jsonb, 2);
insert into public.trail_checkpoint (trail_id, seq, name, poi_id, location, radius_m, exercise, coaching) values
  ('T02', 1, 'Start: Sisi Barat Laut', null, extensions.st_setsrid(extensions.st_makepoint(107.641662, -6.915208), 4326)::extensions.geography, 25, 'Pemanasan dinamis', 'Selamat datang di Jogging Lingkar Kiara Artha! Pemanasan dinamis dulu: angkat lutut bergantian selama tiga puluh detik. Lalu mulai jogging pelan searah jarum jam.'),
  ('T02', 2, 'Sisi Timur Laut', null, extensions.st_setsrid(extensions.st_makepoint(107.64313, -6.915489), 4326)::extensions.geography, 25, 'Atur ritme napas', 'Checkpoint dua, sisi timur laut. Atur ritme napas: tarik napas dua langkah, hembuskan dua langkah. Kamu seharusnya masih bisa ngobrol dengan nyaman.'),
  ('T02', 3, 'Sisi Tenggara', null, extensions.st_setsrid(extensions.st_makepoint(107.642854, -6.917028), 4326)::extensions.geography, 25, 'Postur lari', 'Checkpoint tiga, sisi tenggara. Cek postur: badan tegak sedikit condong ke depan, lengan menekuk sembilan puluh derajat, dan mendarat dengan tengah telapak kaki.'),
  ('T02', 4, 'Sisi Barat Daya', null, extensions.st_setsrid(extensions.st_makepoint(107.641434, -6.916829), 4326)::extensions.geography, 25, 'Jaga kecepatan', 'Checkpoint empat, sisi barat daya. Sedikit lagi! Pertahankan kecepatan yang nyaman. Area kuliner ada di sebelah kananmu kalau mau istirahat setelah ini.'),
  ('T02', 5, 'Finish: Sisi Barat Laut', null, extensions.st_setsrid(extensions.st_makepoint(107.641662, -6.915208), 4326)::extensions.geography, 25, 'Pendinginan', 'Satu putaran selesai, keren! Jalan pelan dua menit untuk pendinginan, lalu regangkan betis dengan bertumpu pada dinding atau pohon.');
insert into public.badge (id, name, description, poi_ids, min_count, requires_trail, kind, sort_order) values
  ('B01', 'Langkah Pertama', 'Kumpulkan stempel pertama Anda.', '{}'::text[], 1, false, 'stamp', 1),
  ('B02', 'Penjelajah Danau', 'Kunjungi 3 spot di sekitar danau.', array['P03', 'P05', 'P11']::text[], 3, false, 'stamp', 2),
  ('B03', 'Pencicip Kuliner', 'Kunjungi 2 dari 3 area kuliner dan kafe.', array['P08', 'P09', 'P15']::text[], 2, false, 'stamp', 3),
  ('B04', 'Sahabat Sehat', 'Kunjungi 3 spot wellness dan selesaikan satu Wellness Trail.', array['P06', 'P07', 'P11']::text[], 3, true, 'stamp', 4),
  ('B05', 'Penjelajah Sejati', 'Kumpulkan seluruh 14 stempel Kiara Artha Park.', array['P01', 'P02', 'P03', 'P05', 'P06', 'P07', 'P08', 'P09', 'P11', 'P12', 'P13', 'P14', 'P15', 'P16']::text[], 14, false, 'stamp', 5),
  ('B06', 'Penjawab Jitu', 'Jawab benar kuis di 6 spot.', '{}'::text[], 6, false, 'quiz', 6),
  ('B07', 'Misi Tuntas', 'Selesaikan misi di 6 spot.', '{}'::text[], 6, false, 'mission', 7),
  ('B08', 'Juru Foto', 'Selesaikan 3 misi foto.', '{}'::text[], 3, false, 'photo', 8),
  ('B09', 'Langganan Taman', 'Berkunjung 3 minggu berturut-turut.', '{}'::text[], 3, false, 'streak', 9);
insert into public.quiz_question (poi_id, trail_id, seq, question, options, answer_index, explanation) values
  ('P01', null, 1, 'Kapan Kiara Artha Park diresmikan?', array['17 Agustus 2019', '24 April 2019', '1 Januari 2020', '17 Agustus 2015']::text[], 0, 'Taman ini diresmikan 17 Agustus 2019, bertepatan dengan HUT ke-74 Republik Indonesia.'),
  ('P01', null, 2, 'Kiara Artha Park berada di antara dua flyover. Flyover apa saja?', array['Pelangi dan Pasupati', 'Pasupati dan Cimindi', 'Cimindi dan Antapani', 'Antapani dan Kiaracondong']::text[], 3, 'Taman ini terletak di antara flyover Antapani dan flyover Kiaracondong, Kelurahan Kebonwaru.'),
  ('P02', null, 1, 'Berapa tiket masuk per orang menurut detikJabar (2024)?', array['Gratis', 'Rp5.000', 'Rp10.000', 'Rp25.000']::text[], 2, 'Tiket tercatat Rp10.000 per orang, hari kerja maupun akhir pekan. Cek lagi di loket karena harga bisa berubah.'),
  ('P02', null, 2, 'Dari gerbang parkir, ke arah mana Pintu Utama?', array['Utara, sekitar 300 m', 'Timur, sekitar 500 m', 'Di seberang Jl. Banten', 'Selatan, sekitar 90 m']::text[], 3, 'Pintu Utama ada sekitar 90 meter ke arah selatan dari gerbang parkir.'),
  ('P03', null, 1, 'Jam berapa pertunjukan air mancur menari biasanya dimulai?', array['16.00', '21.00', '12.00', '18.30']::text[], 3, 'Pertunjukan umumnya mulai pukul 18.30 sampai 20.30, dengan pertunjukan berbeda tiap jam (Orami, 2024).'),
  ('P03', null, 2, 'Apa nama patung jabat tangan di tepi utara danau?', array['Monumen Persahabatan', 'Patung Merdeka', 'Tugu Asia Afrika', 'Friendship Shake Hand']::text[], 3, 'Patung Friendship Shake Hand menggambarkan jabat tangan persahabatan, sejalan dengan semangat Asia Afrika.'),
  ('P05', null, 1, 'Konferensi Asia Afrika 1955 digelar di gedung apa di Bandung?', array['Gedung Merdeka', 'Layana Hall', 'Gedung Sate', 'Gedung Pakuan']::text[], 0, 'KAA digelar di Gedung Merdeka, Bandung, 18–24 April 1955.'),
  ('P05', null, 2, 'Berapa negara yang hadir di Konferensi Asia Afrika 1955?', array['10 negara', '100 negara', '29 negara', '55 negara']::text[], 2, 'Konferensi Asia Afrika 1955 dihadiri 29 negara.'),
  ('P06', null, 1, 'Kira-kira berapa panjang satu putaran jalur lingkar taman?', array['±750 m', '±2 km', '±200 m', '±5 km']::text[], 0, 'Jalur lingkar Jl. Kiara Artha sekitar 750 meter per putaran.'),
  ('P06', null, 2, 'Acara lari apa yang pernah digelar di Kiara Artha Park?', array['Borobudur Marathon', 'Jakarta Marathon', 'Tour de Bandung', 'Pocari Run 2025']::text[], 3, 'Kiara Artha Park pernah menjadi tuan rumah acara lari Pocari Run 2025.'),
  ('P07', null, 1, 'BOSEH adalah singkatan dari…', array['Bersepeda Olahraga Sehat', 'Bike Of Smart Eco Hub', 'Bandung Ongkos Sepeda Hemat', 'Bike on the Street Everybody Happy']::text[], 3, 'BOSEH = Bike on the Street Everybody Happy, program sepeda sewa Pemkot Bandung.'),
  ('P07', null, 2, 'Berapa tarif resmi BOSEH untuk jam pertama?', array['Rp1.000', 'Rp10.000', 'Rp30.000', 'Rp50.000']::text[], 0, 'Tarif resmi BOSEH tercatat Rp1.000 untuk jam pertama dan Rp2.000 untuk jam berikutnya.'),
  ('P08', null, 1, 'Paket Kiara Pelangi Food Court Rp35.000 disebut sudah termasuk apa?', array['Tiket masuk taman', 'Parkir gratis', 'Sewa sepeda satu jam', 'Akses menonton air mancur menari']::text[], 3, 'Paketnya disebut sudah termasuk akses menonton air mancur menari (Orami, 2024).'),
  ('P08', null, 2, 'Kafe dekat area ini yang punya rating 4,8 dengan lebih dari seribu ulasan di Google Maps?', array['Kopi Kiara', 'Ludo Sports Kitchen and Coffee', 'Padel Co.', 'Kopi Taman Kota']::text[], 1, 'Ludo Sports Kitchen and Coffee punya lebih dari seribu ulasan dengan rating 4,8.'),
  ('P09', null, 1, 'Di negara mana olahraga padel lahir?', array['Brasil', 'Meksiko', 'Spanyol', 'Inggris']::text[], 1, 'Padel lahir di Acapulco, Meksiko, pada 1969.'),
  ('P09', null, 2, 'Apa yang membedakan padel dari tenis?', array['Bola boleh memantul ke dinding', 'Dimainkan tanpa raket', 'Dimainkan sendirian', 'Lapangan tanpa net']::text[], 0, 'Dalam padel, bola boleh memantul ke dinding kaca sebelum dipukul kembali.'),
  ('P11', null, 1, 'Pola napas apa yang Kia ajak latih di Zona Teduh?', array['Tarik 4 hitungan, hembuskan 6', 'Napas cepat 20 kali', 'Tarik 10, tahan 10', 'Tahan napas 1 menit']::text[], 0, 'Menghembuskan napas lebih panjang (6) daripada menarik (4) membantu menenangkan detak jantung.'),
  ('P11', null, 2, 'Mengapa udara di bawah kanopi pohon terasa lebih sejuk?', array['Kanopi menaungi dari terik matahari', 'Ada pendingin udara', 'Karena dekat parkiran', 'Karena tanahnya basah']::text[], 0, 'Kanopi pohon menaungi area di bawahnya sehingga terasa lebih sejuk dibanding area terbuka.'),
  ('P12', null, 1, 'Musala Kiara Artha Park berdekatan dengan gedung apa?', array['Padel Co.', 'Gedung Sate', 'Gedung Merdeka', 'Layana Hall']::text[], 3, 'Musala ini tercatat di Google Maps berdekatan dengan Layana Hall.'),
  ('P12', null, 2, 'Selain di sini, di mana lagi toilet umum tersedia?', array['Di tengah danau', 'Sekitar area parkir sisi barat laut', 'Tidak ada lagi', 'Di Taman Asia Afrika']::text[], 1, 'Toilet umum lain tersedia di sekitar area parkir sisi barat laut taman.'),
  ('P13', null, 1, 'Gerbang Utara menghadap jalan apa?', array['Jl. Asia Afrika', 'Jl. Ibrahim Adjie', 'Jl. Banten', 'Jl. Jakarta']::text[], 3, 'Gerbang Utara ada di sisi Jl. Jakarta, terhubung ke taman lewat Jl. Kiara Artha Utara.'),
  ('P13', null, 2, 'Dari Gerbang Utara, ke arah mana lingkar taman?', array['Lurus ke selatan, ±100 m', 'Ke utara, ±1 km', 'Ke barat, ±500 m', 'Menyeberang Jl. Jakarta']::text[], 0, 'Ikuti Jl. Kiara Artha Utara lurus ke selatan sekitar 100 meter.'),
  ('P14', null, 1, 'Gerbang Timur menghadap jalan apa?', array['Jl. Jakarta', 'Jl. Banten', 'Jl. H. Ibrahim Adjie', 'Jl. Pasirkoja']::text[], 2, 'Gerbang Timur ada di sisi Jl. H. Ibrahim Adjie, arah Kiaracondong.'),
  ('P14', null, 2, 'Spot apa yang tepat berada di sebelah selatan Gerbang Timur?', array['Taman Asia Afrika', 'Food Court 2', 'Selter BOSEH', 'Area parkir']::text[], 1, 'Food Court 2 dengan deretan kafe dan resto ada tepat di sebelah selatan gerbang.'),
  ('P15', null, 1, 'Tenan mana yang ada di Food Court 2?', array['Steak Ranjang', 'Kiara Pelangi', 'Ludo Sports Kitchen', 'Padel Co.']::text[], 0, 'Food Court 2 berisi Steak Ranjang, Siloka, Pang Waffle, dan RD Coffee & Eatery.'),
  ('P15', null, 2, 'Kira-kira berapa jarak Food Court 2 ke danau?', array['±10 m', '±140 m', '±600 m', '±1 km']::text[], 1, 'Danau dan air mancur sekitar 140 meter ke arah barat dari sini.'),
  ('P16', null, 1, 'Masjid Al-Maleeq berada di sisi mana kawasan Kiara Artha?', array['Barat, dekat Jl. Banten', 'Timur, dekat Jl. Ibrahim Adjie', 'Di tengah danau', 'Selatan, di Kiara Pelangi']::text[], 0, 'Masjid Al-Maleeq ada di sisi barat, di pojok deretan toko dekat Jl. Banten.'),
  ('P16', null, 2, 'Selain masjid ini, di mana lagi bisa salat di taman?', array['Selter BOSEH', 'Food Court 2', 'Musala dekat Layana Hall', 'Lapangan padel']::text[], 2, 'Ada musala di sisi utara taman, dekat Layana Hall dan titik start jogging track.'),
  (null, 'T01', 1, 'Pola napas di Rute Santai: tarik berapa hitungan, hembuskan berapa?', array['Tarik 10, hembuskan 10', 'Tarik 2, hembuskan 2', 'Tarik 6, hembuskan 4', 'Tarik 4, hembuskan 6']::text[], 3, 'Hembusan yang lebih panjang (6) dari tarikan (4) membantu tubuh lebih rileks.'),
  (null, 'T01', 2, 'Setelah selesai berjalan, sebaiknya kamu…', array['Langsung lari sprint', 'Tidak perlu apa-apa', 'Pendinginan dan minum air', 'Duduk tanpa bergerak lama']::text[], 2, 'Pendinginan meregangkan otot, dan minum air mengganti cairan yang keluar.'),
  (null, 'T02', 1, 'Saat jogging dengan ritme nyaman, kamu seharusnya…', array['Menahan napas', 'Masih bisa ngobrol dengan nyaman', 'Berhenti tiap 10 meter', 'Terengah-engah tak bisa bicara']::text[], 1, 'Kalau masih bisa ngobrol, intensitas jogging-mu pas.'),
  (null, 'T02', 2, 'Posisi lengan yang dianjurkan saat berlari?', array['Menekuk sekitar 90 derajat', 'Dimasukkan ke saku', 'Lurus kaku ke bawah', 'Diangkat di atas kepala']::text[], 0, 'Lengan menekuk 90 derajat membantu ayunan yang efisien.');
insert into public.mission (poi_id, type, title, prompt, done_label, seconds, cues) values
  ('P01', 'photo', 'Foto pertama di Jurnal', 'Foto gerbang barat dari tempatmu berdiri. Ini jadi halaman pertama Jurnal Kunjunganmu!', null, null, '[]'::jsonb),
  ('P02', 'confirm', 'Ingat tempat parkirmu', 'Catat blok atau patokan tempat kendaraanmu diparkir supaya mudah ditemukan saat pulang.', 'Sudah kucatat!', null, '[]'::jsonb),
  ('P03', 'confirm', 'Cari patung jabat tangan', 'Lihat ke tepi utara danau dan temukan patung Friendship Shake Hand, dua tangan yang berjabat.', 'Ketemu!', null, '[]'::jsonb),
  ('P05', 'photo', 'Foto ikonik Asia Afrika', 'Menghadaplah ke utara dan ambil foto berlatar danau dan air mancur.', null, null, '[]'::jsonb),
  ('P06', 'timer', 'Pemanasan 60 detik', 'Ikuti aba-aba Kia sampai waktunya habis. Gerakkan badan pelan-pelan saja.', null, 60, '[{"at":0,"text":"Putar pergelangan kaki kanan."},{"at":15,"text":"Ganti, putar pergelangan kaki kiri."},{"at":30,"text":"Ayunkan kedua lengan ke depan dan ke belakang."},{"at":45,"text":"Sekarang jalan di tempat."}]'::jsonb),
  ('P07', 'confirm', 'Intip selter BOSEH', 'Lihat ke selter: ada sepeda yang siap disewa sekarang? Perhatikan juga papan tarifnya.', 'Sudah kuintip!', null, '[]'::jsonb),
  ('P08', 'photo', 'Foto menu favorit', 'Foto makanan atau minuman yang paling menggoda di area kuliner.', null, null, '[]'::jsonb),
  ('P09', 'confirm', 'Tonton satu reli', 'Tonton pemain padel sampai satu reli selesai. Perhatikan bola yang memantul ke dinding kaca!', 'Sudah kutonton!', null, '[]'::jsonb),
  ('P11', 'timer', 'Napas 4-6 selama 60 detik', 'Tarik napas 4 hitungan, hembuskan 6 hitungan. Ikuti aba-aba Kia.', null, 60, '[{"at":0,"text":"Tarik napas."},{"at":4,"text":"Hembuskan perlahan."},{"at":10,"text":"Tarik napas."},{"at":14,"text":"Hembuskan perlahan."},{"at":20,"text":"Tarik napas."},{"at":24,"text":"Hembuskan perlahan."},{"at":30,"text":"Tarik napas."},{"at":34,"text":"Hembuskan perlahan."},{"at":40,"text":"Tarik napas."},{"at":44,"text":"Hembuskan perlahan."},{"at":50,"text":"Tarik napas."},{"at":54,"text":"Hembuskan perlahan."}]'::jsonb),
  ('P12', 'confirm', 'Jaga kebersihan', 'Simpan alas kaki di rak dan buang satu sampah yang kamu lihat ke tempatnya.', 'Sudah!', null, '[]'::jsonb),
  ('P13', 'confirm', 'Hitung langkahmu', 'Hitung langkahmu dari gerbang sampai lingkar taman. Lebih atau kurang dari 150 langkah?', 'Sudah kuhitung!', null, '[]'::jsonb),
  ('P14', 'confirm', 'Cari papan nama', 'Temukan papan nama atau tulisan Kiara Artha Park di sekitar gerbang timur.', 'Ketemu!', null, '[]'::jsonb),
  ('P15', 'photo', 'Foto menu Food Court 2', 'Foto menu atau tenan favoritmu di Food Court 2.', null, null, '[]'::jsonb),
  ('P16', 'confirm', 'Rapikan alas kaki', 'Simpan alas kakimu dengan rapi di tempat yang disediakan, lalu bantu rapikan satu pasang lainnya.', 'Sudah rapi!', null, '[]'::jsonb);
insert into public.kia_faq (id, patterns, answer, poi_id, sort_order) values
  ('tiket', array['tiket', 'harga masuk', 'bayar masuk', 'htm', 'biaya masuk']::text[], 'Tiket masuk tercatat Rp10.000 per orang, hari kerja maupun akhir pekan (detikJabar, 2024). Cek lagi di loket, ya, harga bisa berubah.', 'P02', 1),
  ('alamat', array['alamat', 'lokasi taman', 'letak taman', 'taman ini di mana']::text[], 'Kiara Artha Park ada di Jl. Banten, Kebonwaru, Kecamatan Batununggal, Kota Bandung, di antara flyover Antapani dan flyover Kiaracondong.', 'P01', 2),
  ('kontak', array['kontak', 'telepon', 'nomor hp', 'nomor telepon', 'instagram', 'ig', 'pengelola']::text[], 'Info resmi taman: Instagram @kiaraarthapark dan telepon 0822-1583-8889.', null, 3),
  ('angkutan', array['angkot', 'bus', 'transportasi', 'naik apa', 'trans metro', 'kendaraan umum', 'halte']::text[], 'Bus Trans Metro Bandung Koridor 5 berhenti di halte Kiara Artha. Dari selter BOSEH di sisi barat, kamu juga bisa lanjut bersepeda.', 'P07', 4),
  ('sewa', array['sewa sepeda', 'skuter', 'otoped', 'harga sepeda', 'tarif sepeda', 'boseh']::text[], 'BOSEH (sepeda Pemkot Bandung) mulai Rp1.000 untuk jam pertama. Sewa sepeda dan skuter listrik di dalam taman sekitar Rp30.000 di hari kerja dan Rp40.000 di akhir pekan (detikJabar, 2024).', 'P07', 5),
  ('paket', array['paket', 'food court', 'makan malam', 'paket makan']::text[], 'Paket Kiara Pelangi Food Court Rp35.000 disebut sudah termasuk akses menonton air mancur menari (Orami, 2024). Konfirmasi lagi di lokasi, ya.', 'P08', 6),
  ('padel', array['booking padel', 'sewa lapangan', 'reservasi', 'pesan lapangan', 'main padel']::text[], 'Lapangan padel dipesan langsung ke pengelola Padel Co. SETARA belum menyediakan reservasi.', 'P09', 7),
  ('masjid', array['salat jumat', 'jumatan', 'masjid besar', 'al maleeq', 'al-maleeq']::text[], 'Untuk salat, ada Masjid Al-Maleeq di sisi barat dekat Jl. Banten dan Pintu Utama, serta musala dekat Layana Hall di sisi utara taman.', 'P16', 8),
  ('kia', array['kamu siapa', 'siapa kamu', 'kia siapa', 'siapa kia', 'kenalan']::text[], 'Aku Kia, tunas pohon kiara! Aku menemanimu menjelajah, membacakan cerita spot, dan memberi kuis serta misi. Makin banyak bintang yang kamu kumpulkan, makin tinggi aku tumbuh.', null, 9),
  ('kiara', array['pohon kiara', 'asal nama', 'arti kiara', 'nama kiara']::text[], 'Kiara adalah pohon sejenis beringin (Ficus). Nama Kiaracondong konon berasal dari pohon kiara yang tumbuh condong.', null, 10),
  ('privasi', array['privasi', 'data saya', 'lokasi saya dikirim', 'aman nggak']::text[], 'Lokasimu hanya diproses di ponsel dan tidak pernah dikirim ke server. Yang terkirim tanpa identitas hanya rating, laporan, hasil kuis, dan pertanyaan yang belum bisa kujawab.', null, 11);
