-- SETARA — isi konten database (dibuat otomatis oleh scripts/build-data.mjs; jangan edit manual)
-- Versi dataset: 2026-11-24. Mengganti data simulasi dengan data Kiara Artha Park (koordinat Google Maps).
-- Jalankan SETELAH migrasi 20261116000000_setara_lengkapi_skema.sql, 20261119000000_setara_interaksi_dua_arah.sql, dan 20261124000000_setara_akun_pengguna.sql
begin;

  on conflict (id) do update set data = excluded.data, version = excluded.version, updated_at = now();

-- Kategori (atribut tampilan)
update public.category set color = '#ee7b5b', icon = 'sparkle', sort_order = 1 where id = 'atraksi';
update public.category set color = '#3f9e8e', icon = 'pulse', sort_order = 2 where id = 'wellness';
update public.category set color = '#e09a2d', icon = 'cup', sort_order = 3 where id = 'kuliner';
update public.category set color = '#d4709c', icon = 'balloon', sort_order = 4 where id = 'keluarga';
update public.category set color = '#4a93c4', icon = 'facility', sort_order = 5 where id = 'fasilitas';
update public.category set color = '#5d7d77', icon = 'gate', sort_order = 6 where id = 'akses';

