-- POI yang sudah tidak ada di lapangan (mis. Kampung Korea, Lolipops Playland) disembunyikan, bukan dihapus,
-- agar umpan balik lama yang merujuk ke POI tersebut tetap utuh.
update public.poi set is_published = false where id not in ('P01', 'P02', 'P03', 'P05', 'P06', 'P07', 'P08', 'P09', 'P11', 'P12', 'P13', 'P14', 'P15', 'P16');

-- Kategori ganda (P09 = Kuliner & Wellness)
delete from public.poi_category;

-- Trivia (≥1 per POI; is_verified = bersumber dokumen/Google Maps)
delete from public.trivia;

-- Foto: path di bucket poi-media (unggah berkas dengan nama ini); keterangan = foto yang perlu diambil
delete from public.photo where poi_id in ('P01', 'P02', 'P03', 'P05', 'P06', 'P07', 'P08', 'P09', 'P11', 'P12', 'P13', 'P14', 'P15', 'P16');

-- Audio narasi: path di bucket poi-media; durasi = estimasi naskah narasi (TTS dipakai sampai berkas diunggah)
delete from public.audio where poi_id in ('P01', 'P02', 'P03', 'P05', 'P06', 'P07', 'P08', 'P09', 'P11', 'P12', 'P13', 'P14', 'P15', 'P16');

-- Jam operasional per hari (0 = Minggu … 6 = Sabtu)
delete from public.schedule where poi_id in ('P01', 'P02', 'P03', 'P05', 'P06', 'P07', 'P08', 'P09', 'P11', 'P12', 'P13', 'P14', 'P15', 'P16');

-- Jadwal atraksi
delete from public.poi_event;

-- Wellness Trail & checkpoint
delete from public.trail_checkpoint; delete from public.wellness_trail;

-- Badge koleksi stempel
delete from public.badge;

-- Interaksi dua arah (migrasi 20261119000000): kuis, misi, Tanya Kia, Tantangan Hari Ini
